class Solution:
    def minDeliveryTime(self, d: List[int], r: List[int]) -> int:
        from math import gcd
        L = r[0] * r[1] // gcd(r[0], r[1])
        def ok(T):
            return (T - T // r[0] >= d[0] and T - T // r[1] >= d[1]
                    and T - T // L >= d[0] + d[1])
        T = 1
        while not ok(T):
            T += 1
        return T

