class Solution {
public:
    int minDeliveryTime(vector<int>& d, vector<int>& r) {
        long long g = __gcd((long long)r[0], (long long)r[1]);
        long long L = (long long)r[0] / g * r[1];
        auto ok = [&](long long T) {
            return T - T / r[0] >= d[0] && T - T / r[1] >= d[1]
                && T - T / L >= (long long)d[0] + d[1];
        };
        long long T = 1;
        while (!ok(T)) T++;
        return (int)T;
    }
};

