class Solution {
    public int minDeliveryTime(int[] d, int[] r) {
        long L = (long) r[0] / gcd(r[0], r[1]) * r[1];
        long T = 1;
        while (!ok(T, d, r, L)) T++;
        return (int) T;
    }
    private boolean ok(long T, int[] d, int[] r, long L) {
        return T - T / r[0] >= d[0] && T - T / r[1] >= d[1]
            && T - T / L >= (long) d[0] + d[1];
    }
    private long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }
}

